export function parseCSV(text) {
  if (typeof text !== 'string') throw new Error('CSV must be a string');
  if (!text.length) return [];
  const rows = []; let row = [], field = '', state = 'start';
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (state === 'quoted') {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; }
        else state = 'closed';
      } else field += c;
      continue;
    }
    if (c === ',') { row.push(field); field = ''; state = 'start'; }
    else if (c === '\r' || c === '\n') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(field); rows.push(row); row = []; field = ''; state = 'start';
      if (i === text.length - 1) return rows;
    } else if (c === '"' && state === 'start') state = 'quoted';
    else {
      if (c === '"' || state === 'closed') throw new Error('Invalid CSV quote');
      field += c; state = 'plain';
    }
  }
  if (state === 'quoted') throw new Error('Unclosed CSV quote');
  row.push(field); rows.push(row); return rows;
}
export function stringifyCSV(rows) {
  if (!Array.isArray(rows)) throw new Error('Invalid CSV rows');
  return rows.map(row => {
    if (!Array.isArray(row)) throw new Error('Invalid CSV row');
    return row.map(value => {
      const s = String(value);
      return /[",\r\n]/.test(s) ? `"${s.replaceAll('"', '""')}"` : s;
    }).join(',');
  }).join('\r\n');
}

const pattern = /^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(?:-([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?$/;
export function parseVersion(text) {
  const match = typeof text === 'string' && pattern.exec(text);
  if (!match) throw new Error('Invalid version');
  const prerelease = match[4] ? match[4].split('.') : [];
  if (prerelease.some(p => /^\d+$/.test(p) && p.length > 1 && p[0] === '0')) throw new Error('Invalid prerelease version');
  return {major: Number(match[1]), minor: Number(match[2]), patch: Number(match[3]), prerelease};
}
const cmp = (a, b) => a < b ? -1 : a > b ? 1 : 0;
export function compareVersions(a, b) {
  const av = parseVersion(a), bv = parseVersion(b);
  const ab = a.split('-')[0].split('.'), bb = b.split('-')[0].split('.');
  for (let i = 0; i < 3; i++) { const n = cmp(BigInt(ab[i]), BigInt(bb[i])); if (n) return n; }
  if (!av.prerelease.length || !bv.prerelease.length) return cmp(!av.prerelease.length, !bv.prerelease.length);
  for (let i = 0; i < Math.min(av.prerelease.length, bv.prerelease.length); i++) {
    const x = av.prerelease[i], y = bv.prerelease[i], xn = /^\d+$/.test(x), yn = /^\d+$/.test(y);
    const n = xn && yn ? cmp(BigInt(x), BigInt(y)) : xn !== yn ? (xn ? -1 : 1) : cmp(x, y);
    if (n) return n;
  }
  return cmp(av.prerelease.length, bv.prerelease.length);
}

